INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52218, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自然の中で生まれ育ち、人間の手で飼育・栽培されていない状態。", "primary_collocate": null, "pronunciation": "やせい", "ipa": "jasei", "syllable_count": 3, "sentences": [{"text": "修業の途上にある若きパン職人は、夜明け前の凛とした空気が張り詰めるアトリエにて、野生の酵母が織りなす微細かつ劇的な化学反応と黙々と格闘していた。", "target_word": "野生", "complexity_tier": "T6", "furigana": "やせい", "sentence_source": "mined"}, {"text": "静謐な工房において、作り手は野生酵母と乳酸菌の共生するサワードウの種起こしから営為を開始する。", "target_word": "野生酵母", "complexity_tier": "T6", "furigana": "やせい", "sentence_source": "mined"}, {"text": "野生の猿が山で暮らしている。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生で育った花は強い。", "target_word": "野生", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "森には野生の動物がまだ残っている。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生のキノコを食べるのは危ないので、よく調べてからにしてください。", "target_word": "野生の", "complexity_tier": "T5", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生の本能を失った犬は、森では生きられない。", "target_word": "野生の", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生に戻された鳥は、すぐに空へ飛んでいった。", "target_word": "野生に", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生と飼育の違いを説明してください。", "target_word": "野生", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}, {"text": "この魚は野生ではなく、養殖です。", "target_word": "野生", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "野生の", "label": "派生"}, {"form": "野生化", "label": "派生"}, {"form": "野生動物", "label": "派生"}, {"form": "野生種", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 飼育されず自然のままの状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 張り詰める (Zipf 1.07)','sentence 1 above tier T3: contains vocabulary far above tier T3: 営為 (Zipf 1.88)']::text[], '747efe4e-8f91-4c86-9290-4941a9662935') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52217, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "人が育てていない、自然のままの生き物のこと。", "primary_collocate": null, "pronunciation": "やせい", "ipa": "jasei", "syllable_count": 3, "sentences": [{"text": "野生の馬が走っています。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "私は野生のサルを見ました。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "この鳥は野生です。", "target_word": "野生", "complexity_tier": "T1", "furigana": "やせい", "sentence_source": "generated"}, {"text": "山には野生の動物がいます。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生で生きる動物は強いです。", "target_word": "野生", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生の花を取らないでください。", "target_word": "野生の", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生は、きびしい世界です。", "target_word": "野生", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "動物園の動物は野生ではありません。", "target_word": "野生", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}, {"text": "野生に戻った猫は、人をこわがる。", "target_word": "野生に", "complexity_tier": "T2", "furigana": "やせい", "sentence_source": "generated"}, {"text": "動物は野生で育つのが一番いいです。", "target_word": "野生", "complexity_tier": "T3", "furigana": "やせい", "sentence_source": "generated"}], "morphological_forms": [{"form": "野生の", "label": "派生"}, {"form": "野生化", "label": "派生"}, {"form": "野生動物", "label": "派生"}, {"form": "野生種", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人が育てない自然のままの生き物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1',