INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52440, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まだ知られていないこと。わからないこと。", "primary_collocate": null, "pronunciation": "みち", "ipa": "mit͡ɕi", "syllable_count": 2, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "未知の", "complexity_tier": "T6", "furigana": "みち", "sentence_source": "mined"}, {"text": "教室という微型社会において、彼女は未知の友達とどのように接し、どのようになじんでいくのだろうか。", "target_word": "未知の", "complexity_tier": "T6", "furigana": "みち", "sentence_source": "mined"}, {"text": "凍てつく空気の中、ボタンを一つひとつ留める仕草には、未知の領域へ挑む戦士のような厳粛ささえ漂っていた。", "target_word": "未知の", "complexity_tier": "T6", "furigana": "みち", "sentence_source": "mined"}, {"text": "未知の世界に行ってみたい。", "target_word": "未知の", "complexity_tier": "T2", "furigana": "みち", "sentence_source": "generated"}, {"text": "この病気の原因は、まだ未知です。", "target_word": "未知", "complexity_tier": "T2", "furigana": "みち", "sentence_source": "generated"}, {"text": "未知への不安より、楽しみの方が大きい。", "target_word": "未知", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "結果は未知だが、挑戦する価値はある。", "target_word": "未知", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "その分野は、研究者にとってもまだ未知だ。", "target_word": "未知", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "未知を恐れていては、何も始まらない。", "target_word": "未知", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "宇宙には、まだ未知のことがたくさんある。", "target_word": "未知の", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}], "morphological_forms": [{"form": "未知の", "label": "活用"}, {"form": "未知数", "label": "派生"}, {"form": "未知なる", "label": "派生"}, {"form": "未知への", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | まだ知られていないこと", "collocate_grounding": {"stat