INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52439, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "まだ知らないこと。", "primary_collocate": null, "pronunciation": "みち", "ipa": "mit͡ɕi", "syllable_count": 2, "sentences": [{"text": "彼女は未知の街を歩いた。", "target_word": "未知の", "complexity_tier": "T2", "furigana": "みち", "sentence_source": "generated"}, {"text": "学ぶことの多くは、私には未知だった。", "target_word": "未知", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "この薬の効果はまだ未知です。", "target_word": "未知", "complexity_tier": "T2", "furigana": "みち", "sentence_source": "generated"}, {"text": "未知の味に挑戦してみた。", "target_word": "未知の", "complexity_tier": "T2", "furigana": "みち", "sentence_source": "generated"}, {"text": "山の奥は、人にとって未知の場所だった。", "target_word": "未知の", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "未知を既知に変えるのが、科学の仕事だ。", "target_word": "未知を", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "私には、すべてが未知で、少し怖かった。", "target_word": "未知で", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "未知への挑戦が、人を成長させる。", "target_word": "未知への", "complexity_tier": "T2", "furigana": "みち", "sentence_source": "generated"}, {"text": "先のことは未知だから、今を大切にしたい。", "target_word": "未知", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}, {"text": "その島のことは、誰にとっても未知である。", "target_word": "未知", "complexity_tier": "T3", "furigana": "みち", "sentence_source": "generated"}], "morphological_forms": [{"form": "未知の", "label": "活用"}, {"form": "未知数", "label": "派生"}, {"form": "未知なる", "label": "派生"}, {"form": "未知への", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | まだ知らないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v