INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52454, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "建物や部屋の出入り口に取り付けられ、開閉して出入りを可能にする設備。", "primary_collocate": null, "pronunciation": "とびら", "ipa": "tobiɾa", "syllable_count": 3, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "扉", "complexity_tier": "T6", "furigana": "とびら", "sentence_source": "mined"}, {"text": "やがて準備が整い、彼は勢いよく扉を押し開ける。", "target_word": "扉", "complexity_tier": "T6", "furigana": "とびら", "sentence_source": "mined"}, {"text": "扉が静かに開いた。", "target_word": "扉", "complexity_tier": "T1", "furigana": "とびら", "sentence_source": "generated"}, {"text": "部屋の扉を閉めてください。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "風で扉がバタンと閉まった。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉の向こうから、話し声が聞こえる。", "target_word": "扉", "complexity_tier": "T3", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉に鍵をかけるのを忘れた。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉は重くて、一人では開けられない。", "target_word": "扉", "complexity_tier": "T3", "furigana": "とびら", "sentence_source": "generated"}, {"text": "彼は扉を軽くノックして、中に入った。", "target_word": "扉", "complexity_tier": "T3", "furigana": "とびら", "sentence_source": "generated"}, {"text": "古い扉のペンキが、少しはげている。", "target_word": "扉", "complexity_tier": "T3", "furigana": "とびら", "sentence_source": "generated"}], "morphological_forms": [{"form": "扉の", "label": "活用"}, {"form": "一枚の扉", "label": "助数詞"}, {"form": "玄関扉", "label": "派生"}, {"form": "扉絵", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 出入り口を開閉する設備", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::