INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52453, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "家や部屋の入り口にある、開け閉めできる大きな板のこと。", "primary_collocate": null, "pronunciation": "とびら", "ipa": "tobiɾa", "syllable_count": 3, "sentences": [{"text": "この扉は大きいです。", "target_word": "扉", "complexity_tier": "T1", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉を開けて、中に入りました。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉の前に、犬がいます。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉が閉まっています。", "target_word": "扉", "complexity_tier": "T1", "furigana": "とびら", "sentence_source": "generated"}, {"text": "赤い扉の家が、私の友達の家です。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉をたたくと、誰かが出てきた。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "家の扉に、名前の札がある。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉は外へ開く。", "target_word": "扉", "complexity_tier": "T1", "furigana": "とびら", "sentence_source": "generated"}, {"text": "強い風で、扉が壊れてしまった。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}, {"text": "扉の鍵を、かばんの中に入れた。", "target_word": "扉", "complexity_tier": "T2", "furigana": "とびら", "sentence_source": "generated"}], "morphological_forms": [{"form": "扉の", "label": "活用"}, {"form": "一枚の扉", "label": "助数詞"}, {"form": "玄関扉", "label": "派生"}, {"form": "扉絵", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 入り口の開け閉めできる板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '747efe