INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52460, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事に興味を持ち、知りたいと思う心。また、そのさま。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "好奇心", "complexity_tier": "T6", "furigana": "こうき", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "好奇心", "complexity_tier": "T6", "furigana": "こうき", "sentence_source": "mined"}, {"text": "みんなが好奇の目で彼を見ていた。", "target_word": "好奇の", "complexity_tier": "T2", "furigana": "こうき", "sentence_source": "generated"}, {"text": "子どもたちは好奇に満ちた顔で、窓の外をのぞいた。", "target_word": "好奇に", "complexity_tier": "T4", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇の視線を感じて、彼は急いで立ち去った。", "target_word": "好奇の", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "彼女の好奇は、実験を重ねるうちにさらに強まった。", "target_word": "好奇", "complexity_tier": "T4", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇から始めた研究が、大発見につながった。", "target_word": "好奇", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇のまなざしを向けられるのは、あまり好きではない。", "target_word": "好奇の", "complexity_tier": "T4", "furigana": "こうき", "sentence_source": "generated"}, {"text": "犬は好奇の目を輝かせて、箱を見つめている。", "target_word": "好奇の", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇が不安に勝って、彼はドアを開けた。", "target_word": "好奇", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}], "morphological_forms": [{"form": "好奇の", "label": "活用"}, {"form": "好奇心", "label": "派生"}, {"form": "好奇心旺盛", "label": "派生"}, {"form": "好奇に満ちた", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 物事を知りたいと思う心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 漲っ (Zipf 1.92)','sentence 1 above tier T3: 6 words above tier T3 (max 3): 苛烈 (Zipf 2.89), 寒風 (Zipf 2.18), 携え (Zipf 3.23), 駆け出し (Zipf 3.07), 逞し (Zipf 2.19), 凝縮 (Zipf 3.38)']::text[], '747efe4e-8f91-4c86-9290-4941a9662935') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52459, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "知らないことを知りたいと思う気持ち。", "primary_collocate": null, "pronunciation": "こうき", "ipa": "koːki", "syllable_count": 3, "sentences": [{"text": "子どもは好奇の目で空を見た。", "target_word": "好奇の", "complexity_tier": "T2", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇がわいて、箱を開けてみた。", "target_word": "好奇", "complexity_tier": "T2", "furigana": "こうき", "sentence_source": "generated"}, {"text": "彼の好奇は、とても強い。", "target_word": "好奇", "complexity_tier": "T2", "furigana": "こうき", "sentence_source": "generated"}, {"text": "猫は好奇に満ちた目で、虫を見ている。", "target_word": "好奇に", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇だけで人のことを聞くのは、よくない。", "target_word": "好奇", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "みんなが好奇の目で、新しい先生を見た。", "target_word": "好奇の", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇から、彼は本を読み始めた。", "target_word": "好奇", "complexity_tier": "T2", "furigana": "こうき", "sentence_source": "generated"}, {"text": "赤ちゃんは好奇のまなざしで、私を見つめた。", "target_word": "好奇の", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇を満たすために、図書館へ行きました。", "target_word": "好奇を", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}, {"text": "好奇に負けて、ひみつの手紙を読んでしまった。", "target_word": "好奇に", "complexity_tier": "T3", "furigana": "こうき", "sentence_source": "generated"}], "morphological_forms": [{"form": "好奇の", "label": "活用"}, {"form": "好奇心", "label": "派生"}, {"form": "好奇心旺盛", "label": "派生"}, {"form": "好奇に満ちた", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | 知りたいと思う気持ち", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '747efe4e-8f91-4c86-9290-4941a9662935') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52470, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人間の体の、首から腰までの後ろ側の部分。", "primary_collocate": null, "pronunciation": "せなか", "ipa": "senaka", "syllable_count": 3, "sentences": [{"text": "未知の空間たる新校舎の扉をくぐる娘の背中には、微かな緊張と、それをはるかに上回る好奇心が漲っていた。", "target_word": "背中", "complexity_tier": "T6", "furigana": "せなか", "sentence_source": "mined"}, {"text": "苛烈な寒風が頬を打つ外の世界へと、無垢な好奇心を携えて駆け出していくその背中には、人間が本来備えている、過酷な環境をも楽しみへと変貌させる逞しさが凝縮されていたのである。", "target_word": "背中", "complexity_tier": "T6", "furigana": "せなか", "sentence_source": "mined"}, {"text": "父は私の背中を軽くたたいた。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "猫が背中を丸めて寝ている。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "背中が痛くて、よく眠れなかった。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "彼は背中に大きなリュックを背負っている。", "target_word": "背中", "complexity_tier": "T3", "furigana": "せなか", "sentence_source": "generated"}, {"text": "母の背中は、いつも大きく見えた。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "背中を向けたまま、彼は何も答えなかった。", "target_word": "背中", "complexity_tier": "T3", "furigana": "せなか", "sentence_source": "generated"}, {"text": "背中の汗を、タオルでふいた。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "壁に背中をつけて、ゆっくり息をはいた。", "target_word": "背中", "complexity_tier": "T3", "furigana": "せなか", "sentence_source": "generated"}], "morphological_forms": [{"form": "背中合わせ", "label": "派生"}, {"form": "背中の", "label": "活用"}, {"form": "背中を", "label": "活用"}, {"form": "背中側", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 体の首から腰の後ろ側", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: 漲っ (Zipf 1.92)','sentence 1 above tier T2: contains vocabulary far above tier T2: 寒風 (Zipf 2.18), 逞し (Zipf 2.19)']::text[], '747efe4e-8f91-4c86-9290-4941a9662935') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52469, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人のうしろの部分。せなか。", "primary_collocate": null, "pronunciation": "せなか", "ipa": "senaka", "syllable_count": 3, "sentences": [{"text": "背中がかゆいです。", "target_word": "背中", "complexity_tier": "T1", "furigana": "せなか", "sentence_source": "generated"}, {"text": "背中をかいてください。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "子どもを背中に乗せて歩いた。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "背中にゴミがついていますよ。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "彼の背中は、広くてたのもしい。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "背中の方から、声が聞こえた。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "母は、私の背中をそっとおした。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "夏は背中に汗をかく。", "target_word": "背中", "complexity_tier": "T1", "furigana": "せなか", "sentence_source": "generated"}, {"text": "背中を向けて、彼女は泣いていた。", "target_word": "背中", "complexity_tier": "T2", "furigana": "せなか", "sentence_source": "generated"}, {"text": "プールで背中を日に焼いてしまった。", "target_word": "背中", "complexity_tier": "T3", "furigana": "せなか", "sentence_source": "generated"}], "morphological_forms": [{"form": "背中合わせ", "label": "派生"}, {"form": "背中の", "label": "活用"}, {"form": "背中を", "label": "活用"}, {"form": "背中側", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 人のうしろ側の部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: たのもしい (Zipf 1.53)']::text[], '747efe4e-8f91-4c86-9290-4941a9662935') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39569, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事を自然の状態やあるがままにしておくこと。また、思いのままに行うこと。", "primary_collocate": null, "pronunciation": "まま", "ipa": "mama", "syllable_count": 2, "sentences": [{"text": "しかし、抽出された液は未だ不安定な色彩に過ぎず、そのままでは時間と共に退色してしまう。", "target_word": "まま", "complexity_tier": "T6", "furigana": "まま", "sentence_source": "mined"}, {"text": "窓を開けたまま、寝てしまった。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "靴をはいたまま、部屋に入らないでください。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "何も言わないまま、彼は帰っていった。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "昔のままの町並みが、今も残っている。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "見たままを話してください。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "思いのままに生きるのは、むずかしい。", "target_word": "まま", "complexity_tier": "T3", "furigana": "まま", "sentence_source": "generated"}, {"text": "彼は言われるがままに動いた。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "この店は、昔のままです。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}, {"text": "立ったまま話すのは、疲れる。", "target_word": "まま", "complexity_tier": "T2", "furigana": "まま", "sentence_source": "generated"}], "morphological_forms": [{"form": "そのまま", "label": "派生"}, {"form": "たまま", "label": "活用"}, {"form": "ままに", "label": "活用"}, {"form": "ままで", "label": "活用"}], "register": "plain", "sense_fingerprint": "名詞 | あるがままの状態・思いのまま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '747efe4e-8f91-4c86-9290-4941a9662935') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
