INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52922, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "目的を達するための技術や方法", "primary_collocate": null, "pronunciation": "じゅつ", "ipa": "dʑɯtsɯ", "syllable_count": 2, "sentences": [{"text": "古来、人類は植物の生命力を繊維に宿す術を磨き上げてきた。", "target_word": "術", "complexity_tier": "T6", "furigana": "じゅつ", "sentence_source": "mined"}, {"text": "この一連の作業は、移ろいやすい自然の産物を、人間の手によって恒久の美へと昇華させる、高度な技術と美意識の結晶なのである。", "target_word": "術", "complexity_tier": "T6", "furigana": "じゅつ", "sentence_source": "mined"}, {"text": "彼は古い染めの術を、弟子に伝えた。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "忍者は、姿を隠す術を身につけていた。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "職人の術に、世界中から注目が集まった。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "彼は人を笑わせる術を知っている。", "target_word": "術", "complexity_tier": "T2", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "長い修行によって、その術を会得した。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "術は、練習を重ねてこそ磨かれる。", "target_word": "術", "complexity_tier": "T2", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "医者は、病気を治す術を研究している。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "先人の術を学ぶことで、技が上達する。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "魔術", "label": "派生"}, {"form": "忍術", "label": "派生"}, {"form": "話術", "label": "派生"}, {"form": "医術", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 目的のための技や方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 1 above tier T2: 5 words above tier T2 (max 3): 移ろい (Zipf 2.5), 産物 (Zipf 3.5), 恒久 (Zipf 3.13), 昇華 (Zipf 3.35), 美意識 (Zipf 3.12)']::text[], '86a5986a-b9a1-4fc7-8ea6-964987ea6967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52921, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものごとをうまくやる方法", "primary_collocate": null, "pronunciation": "じゅつ", "ipa": "dʑɯtsɯ", "syllable_count": 2, "sentences": [{"text": "もう、なす術がありません。", "target_word": "術", "complexity_tier": "T2", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "彼を止める術は、見つからなかった。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "逃げる術もなく、雨に濡れた。", "target_word": "術", "complexity_tier": "T2", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "生きる術を、父から学んだ。", "target_word": "術", "complexity_tier": "T2", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "言葉が通じず、伝える術がない。", "target_word": "術", "complexity_tier": "T2", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "その問題を解く術を、みんなで考えた。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "災害の中で、身を守る術を知ることは大切だ。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "彼女は人と仲良くなる術に長けている。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "失敗を取り戻す術を、彼は探し続けた。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}, {"text": "手紙は、気持ちを知らせる術の一つだった。", "target_word": "術", "complexity_tier": "T3", "furigana": "じゅつ", "sentence_source": "generated"}], "morphological_forms": [{"form": "魔術", "label": "派生"}, {"form": "忍術", "label": "派生"}, {"form": "話術", "label": "派生"}, {"form": "医術", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | ものごとをうまくやる方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86a5986a-b9a1-4fc7-8ea6-964987ea6967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (52924, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "植物の生命力を繊維の中に閉じ込めて持つ", "primary_collocate": null, "pronunciation": "やどす", "ipa": "jadosɯ", "syllable_count": 3, "sentences": [{"text": "古来、人類は植物の生命力を繊維に宿す術を磨き上げてきた。", "target_word": "宿す", "complexity_tier": "T6", "furigana": "やどす", "sentence_source": "mined"}, {"text": "この糸は、草の香りを宿している。", "target_word": "宿して", "complexity_tier": "T2", "furigana": "やどして", "sentence_source": "generated"}, {"text": "染めた布は、藍の深い色を宿す。", "target_word": "宿す", "complexity_tier": "T2", "furigana": "やどす", "sentence_source": "generated"}, {"text": "木綿は、太陽の力を宿した素材だ。", "target_word": "宿した", "complexity_tier": "T2", "furigana": "やどした", "sentence_source": "generated"}, {"text": "麻の繊維に、森の息吹が宿されている。", "target_word": "宿されて", "complexity_tier": "T3", "furigana": "やどされて", "sentence_source": "generated"}, {"text": "職人は、糸に季節の命を宿そうとした。", "target_word": "宿そう", "complexity_tier": "T3", "furigana": "やどそう", "sentence_source": "generated"}, {"text": "繊維に命を宿す術を、祖母が教えてくれた。", "target_word": "宿す", "complexity_tier": "T3", "furigana": "やどす", "sentence_source": "generated"}, {"text": "草木から取った色は、生命力を宿して見える。", "target_word": "宿して", "complexity_tier": "T3", "furigana": "やどして", "sentence_source": "generated"}, {"text": "蚕は、自らの命を糸に宿して、繭を作る。", "target_word": "宿して", "complexity_tier": "T3", "furigana": "やどして", "sentence_source": "generated"}, {"text": "古い着物は、人の思いを宿していた。", "target_word": "宿して", "complexity_tier": "T3", "furigana": "やどして", "sentence_source": "generated"}], "morphological_forms": [{"form": "宿した", "label": "活用"}, {"form": "宿して", "label": "活用"}, {"form": "宿さない", "label": "活用"}, {"form": "宿される", "label": "活用"}], "register": "plain", "sense_fingerprint": "動詞 | 繊維の中に生命力を持たせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86a5986a-b9a1-4fc7-8ea6-964987ea6967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
