INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35094, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "金属", "is_correct": true, "explanation": "「金属」が聞こえた語と同じ。"}, {"text": "漢族", "is_correct": false, "explanation": "「漢族」は見出し語と一音だけ違う別の語。"}, {"text": "親族", "is_correct": false, "explanation": "「親族」は見出し語と一音だけ違う別の語。"}, {"text": "禁足", "is_correct": false, "explanation": "「禁足」は見出し語と一音だけ違う別の語。"}], "explanations": {"金属": "「金属」が聞こえた語と同じ。", "漢族": "「漢族」は見出し語と一音だけ違う別の語。", "親族": "「親族」は見出し語と一音だけ違う別の語。", "禁足": "「禁足」は見出し語と一音だけ違う別の語。"}, "sentence_index": null, "correct_answer": "金属"}, "level_3": {"options": [{"text": "金属", "is_correct": true, "explanation": "「金属」が文の意味に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気」は形は合うが、意味が合わない。"}, {"text": "意見", "is_correct": false, "explanation": "「意見」は形は合うが、意味が合わない。"}, {"text": "時間", "is_correct": false, "explanation": "「時間」は形は合うが、意味が合わない。"}], "explanations": {"金属": "「金属」が文の意味に合う。", "天気": "「天気」は形は合うが、意味が合わない。", "意見": "「意見」は形は合うが、意味が合わない。", "時間": "「時間」は形は合うが、意味が合わない。"}, "sentence_index": 0, "correct_answer": "金属"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "金属を食べて、おなかがいっぱいになった。", "explanation": "金属は食べ物ではないので、「食べる」の目的語に使えない。"}, {"text": "金属は柔らかくて、手で簡単にちぎれる。", "explanation": "金属は固い材料なので、「柔らかくてちぎれる」は意味が合わない。"}, {"text": "今日は金属が降るので、傘を持っていく。", "explanation": "金属は天気ではないので、「降る」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68d810d-6531-4761-a40b-78e26fe52fa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
